const signalStats = `-- name: SignalStats :one
SELECT
  count(*) FILTER (WHERE s.status = 'open')::bigint AS open,
  count(*) FILTER (WHERE s.resolved_at >= $2 AND s.resolved_at < $3 AND s.resolved_by IS NOT NULL)::bigint AS decisions,
  coalesce(avg(extract(epoch FROM s.resolved_at - s.created_at)) FILTER (WHERE s.resolved_at >= $2 AND s.resolved_at < $3 AND s.resolved_by IS NOT NULL), 0)::float8 AS avg_answer_seconds
FROM signals s JOIN workspaces w ON w.id = s.workspace_id
WHERE w.org_id = $1 AND ($4::uuid IS NULL OR s.workspace_id = $4::uuid)
`

type SignalStatsParams struct {
	OrgID        uuid.UUID
	ResolvedAt   *time.Time
	ResolvedAt_2 *time.Time
	WorkspaceID  *uuid.UUID
}

type SignalStatsRow struct {
	Open             int64
	Decisions        int64
	AvgAnswerSeconds float64
}

func (q *Queries) SignalStats(ctx context.Context, arg SignalStatsParams) (SignalStatsRow, error) {
	row := q.db.QueryRow(ctx, signalStats,
		arg.OrgID,
		arg.ResolvedAt,
		arg.ResolvedAt_2,
		arg.WorkspaceID,
	)
	var i SignalStatsRow
	err := row.Scan(&i.Open, &i.Decisions, &i.AvgAnswerSeconds)
	return i, err
}

